  static void Curve(AnimationClip clip,Transform root,Transform target,string property,float[] times,float[] values){var keys=times.Select((t,i)=>new Keyframe(t,values[i])).ToArray();var curve=new AnimationCurve(keys);for(int i=0;i<keys.Length;i++){AnimationUtility.SetKeyLeftTangentMode(curve,i,AnimationUtility.TangentMode.ClampedAuto);AnimationUtility.SetKeyRightTangentMode(curve,i,AnimationUtility.TangentMode.ClampedAuto);}AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve(AnimationUtility.CalculateTransformPath(target,root),typeof(Transform),property),curve);}
  static AnimatorController Controller(Transform root,Dictionary<string,Transform> bones,float front)
  {
   var clips=new Dictionary<string,AnimationClip>();foreach(string name in new[]{"Idle","Drive","Attack","Hit","Death"}){var clip=new AnimationClip{name="SawBot_"+name,frameRate=60};AssetDatabase.CreateAsset(clip,Art+"/SawBot_"+name+".anim");clips[name]=clip;}
   float by=bones["Body"].localPosition.y;foreach(string name in new[]{"Idle","Drive"}){var c=clips[name];float[] t={0,.25f,.5f,.75f,1};Curve(c,root,bones["Body"],"m_LocalPosition.y",t,new[]{by,by+.003f,by,by-.003f,by});Curve(c,root,bones["Body"],"localEulerAnglesRaw.x",t,Enumerable.Repeat(name=="Drive"?front*3:0,5).ToArray());foreach(string side in new[]{"L","R"})Curve(c,root,bones["UpperArm_"+side],"localEulerAnglesRaw.x",t,new[]{0,1.2f,0,-1.2f,0});var settings=AnimationUtility.GetAnimationClipSettings(c);settings.loopTime=true;AnimationUtility.SetAnimationClipSettings(c,settings);}
   float[] at={0,.18f,.45f,.60f,.76f,1.15f};foreach(string side in new[]{"L","R"}){float sign=Mathf.Sign(bones["UpperArm_"+side].position.x);Curve(clips["Attack"],root,bones["UpperArm_"+side],"localEulerAnglesRaw.x",at,new[]{0,-front*30,-front*85,-front*110,-front*70,0});Curve(clips["Attack"],root,bones["UpperArm_"+side],"localEulerAnglesRaw.z",at,new[]{0,-sign*12,-sign*22,-sign*5,sign*8,0});Curve(clips["Attack"],root,bones["Forearm_"+side],"localEulerAnglesRaw.x",at,new[]{0,front*30,front*15,-front*5,-front*10,0});}Curve(clips["Attack"],root,bones["Body"],"localEulerAnglesRaw.x",at,new[]{0,-front*3,-front*6,front*7,front*3,0});AnimationUtility.SetAnimationEvents(clips["Attack"],new[]{new AnimationEvent{time=.6f,functionName="SawImpact"},new AnimationEvent{time=1.14f,functionName="SawRecover"}});
   Curve(clips["Hit"],root,bones["Body"],"localEulerAnglesRaw.x",new[]{0,.05f,.11f,.18f},new[]{0,-front*4,front,0});Curve(clips["Death"],root,bones["Body"],"localEulerAnglesRaw.x",new[]{0,.18f,.35f,.75f,1.25f},new[]{0,-front*8,front*6,front*28,front*32});Curve(clips["Death"],root,bones["Body"],"m_LocalPosition.y",new[]{0,.18f,.35f,.75f,1.25f},new[]{by,by+.005f,by-.005f,by-.04f,by-.04f});foreach(string side in new[]{"L","R"})Curve(clips["Death"],root,bones["UpperArm_"+side],"localEulerAnglesRaw.x",new[]{0,.3f,1.25f},new[]{0,front*8,front*15});
   var controller=AnimatorController.CreateAnimatorControllerAtPath(Art+"/SawBot.controller");controller.AddParameter("MoveSpeed",AnimatorControllerParameterType.Float);controller.AddParameter("Alerted",AnimatorControllerParameterType.Bool);controller.AddParameter("Attack",AnimatorControllerParameterType.Trigger);controller.AddParameter("CancelAttack",AnimatorControllerParameterType.Trigger);controller.AddParameter("OnDamaged",AnimatorControllerParameterType.Trigger);controller.AddParameter("AttackSpeed",AnimatorControllerParameterType.Float);var sm=controller.layers[0].stateMachine;var locomotion=sm.AddState("Locomotion");var blend=new BlendTree{name="IdleDrive",blendType=BlendTreeType.Simple1D,blendParameter="MoveSpeed",useAutomaticThresholds=false};blend.AddChild(clips["Idle"],0);blend.AddChild(clips["Drive"],.4f);AssetDatabase.AddObjectToAsset(blend,controller);locomotion.motion=blend;sm.defaultState=locomotion;var attack=sm.AddState("Attack");attack.motion=clips["Attack"];attack.speedParameter="AttackSpeed";attack.speedParameterActive=true;var enter=locomotion.AddTransition(attack);enter.AddCondition(AnimatorConditionMode.If,0,"Attack");enter.duration=.04f;var exit=attack.AddTransition(locomotion);exit.hasExitTime=true;exit.exitTime=1;exit.duration=.05f;var cancel=attack.AddTransition(locomotion);cancel.AddCondition(AnimatorConditionMode.If,0,"CancelAttack");cancel.duration=.05f;sm.AddState("Death").motion=clips["Death"];
   controller.AddLayer("HitReaction");var layers=controller.layers;layers[1].defaultWeight=1;layers[1].blendingMode=AnimatorLayerBlendingMode.Additive;controller.layers=layers;var hsm=layers[1].stateMachine;var rest=hsm.AddState("Rest");hsm.defaultState=rest;var hit=hsm.AddState("Hit");hit.motion=clips["Hit"];var reaction=hsm.AddAnyStateTransition(hit);reaction.AddCondition(AnimatorConditionMode.If,0,"OnDamaged");reaction.duration=.01f;reaction.canTransitionToSelf=false;var reset=hit.AddTransition(rest);reset.hasExitTime=true;reset.exitTime=1;reset.duration=.04f;return controller;
